bool UFoundrylineNetworkTestTools::QueuePavement(APlayerController* P,FName Mode,const TArray<FVector>& Points,float Width,int32 Lanes,bool Truck,bool Curbs){
#if WITH_EDITOR
 if(!P||!P->IsLocalController()||P->GetWorld()->WorldType!=EWorldType::PIE)return false;TWeakObjectPtr<APlayerController> Weak=P;FTSTicker::GetCoreTicker().AddTicker(FTickerDelegate::CreateLambda([Weak,Mode,Points,Width,Lanes,Truck,Curbs](float){if(auto* S=Site(Weak.Get())){TArray<FVector2D> Flat;for(const auto V:Points)Flat.Add(FVector2D(V));S->PavementShape(Mode,Flat,Width,Lanes,Truck,Curbs);}return false;}));return true;
#else
 return false;
#endif
}
bool UFoundrylineNetworkTestTools::QueuePavementPaint(APlayerController* P,int32 Kind,const TArray<FVector>& Points,float Width){
#if WITH_EDITOR
 if(!P||!P->IsLocalController()||P->GetWorld()->WorldType!=EWorldType::PIE||Kind<0||Kind>7)return false;TWeakObjectPtr<APlayerController> Weak=P;FTSTicker::GetCoreTicker().AddTicker(FTickerDelegate::CreateLambda([Weak,Kind,Points,Width](float){if(auto* S=Site(Weak.Get())){TArray<FVector2D> Flat;for(const auto V:Points)Flat.Add(FVector2D(V));S->AddPavementMark(EFoundrylinePavementMark(Kind),Flat,Width);}return false;}));return true;
#else
 return false;
#endif
}
bool UFoundrylineNetworkTestTools::QueuePavementOption(APlayerController* P,FIntVector Cursor,FName Action){
#if WITH_EDITOR
 if(!P||!P->IsLocalController()||P->GetWorld()->WorldType!=EWorldType::PIE)return false;TWeakObjectPtr<APlayerController> Weak=P;FTSTicker::GetCoreTicker().AddTicker(FTickerDelegate::CreateLambda([Weak,Cursor,Action](float){if(auto* S=Site(Weak.Get())){S->BeginEdit(TEXT("Select"),Cursor);S->PavementOption(Action);}return false;}));return true;
#else
 return false;
#endif
}
bool UFoundrylineNetworkTestTools::ShowPavementTool(APlayerController* P,FName Action){
#if WITH_EDITOR
 auto* PC=Cast<AFoundrylinePlayerController>(P);if(!PC||!PC->IsLocalController()||PC->GetWorld()->WorldType!=EWorldType::PIE)return false;// Editor-reflected helpers must defer RPC mutations until the scripting guard has unwound.
 if(Action==TEXT("BayConfirm")){TWeakObjectPtr<AFoundrylinePlayerController> Weak=PC;FTSTicker::GetCoreTicker().AddTicker(FTickerDelegate::CreateLambda([Weak,Action](float){if(Weak.IsValid())Weak->PavementAction(Action);return false;}));return true;}if(Action.ToString().StartsWith(TEXT("Wheel"))){if(auto* HUD=Cast<AFoundrylineBuildHUD>(PC->GetHUD()))HUD->NotifyHitBoxClick(Action);return true;}if(Action==TEXT("Rect")||Action==TEXT("Polygon")||Action==TEXT("Spline")||Action==TEXT("Road")||Action==TEXT("Erase")||Action==TEXT("AreaMenu")||Action==TEXT("PaintMenu")||Action==TEXT("EditMenu"))if(auto* HUD=Cast<AFoundrylineBuildHUD>(PC->GetHUD()))HUD->NotifyHitBoxClick(TEXT("CategoryRoads"));PC->PavementAction(Action);return true;
#else
 return false;
#endif
}
